import "@xterm/xterm/css/xterm.css";
import { Terminal } from "@xterm/xterm";
import { FitAddon } from "@xterm/addon-fit";
import { Unicode11Addon } from "@xterm/addon-unicode11";
// Generated by `pnpm build:wasm` (wasm-pack --target web) from crates/mustty-web
import init, { Session } from "./pkg/mustty_web.js";
import { followTheme } from "./theme.js";

const toggle = document.getElementById("theme-toggle");
// Swaps the palette in place: the buffer, and so the document and the cursor, stay as they are
const theme = followTheme(toggle, (next) => {
  term.options.theme = next;
  term.refresh(0, term.rows - 1);
});

const term = new Terminal({
  allowProposedApi: true, // the unicode11 width table
  cursorStyle: "bar",
  fontFamily: '"JetBrains Mono", "SF Mono", Menlo, Consolas, "Noto Sans Mono CJK SC", monospace',
  fontSize: 15,
  lineHeight: 1.2,
  macOptionIsMeta: true, // Option+B / Option+F move by word, as in macOS terminals
  theme,
});
const fit = new FitAddon();
term.loadAddon(fit);
term.loadAddon(new Unicode11Addon());
term.unicode.activeVersion = "11";
term.open(document.getElementById("terminal"));
fit.fit();
toggle.addEventListener("click", () => term.focus());

init().then(() => {
  const session = new Session(term.cols, term.rows, (bytes) => term.write(bytes));
  term.onData((data) => session.feed(data));
  term.onResize(({ cols, rows }) => session.resize(cols, rows));
  term.onTitleChange((title) => { document.title = title || "mustty"; });
  addEventListener("resize", () => fit.fit());
  const loop = () => {
    session.frame();
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
  term.focus();
});
